(()=>{function stylePersonnel(){const main=document.querySelector('.shell>.main'),active=!!main?.querySelector('.person-workspace');main?.classList.toggle('personnel-style',active);if(!active)return;main.querySelectorAll('.detail-table').forEach(table=>{if(!table.closest('.person-task-scroll')){const wrap=document.createElement('div');wrap.className='person-task-scroll';wrap.tabIndex=0;wrap.setAttribute('role','region');wrap.setAttribute('aria-label','当前承担的核心专业子单，可横向滚动');table.before(wrap);wrap.append(table)}table.querySelectorAll('tbody tr[data-drill]').forEach(row=>{if(row.querySelector('.person-workitem-link'))return;const title=row.cells[0].querySelector('b');if(!title)return;const button=document.createElement('button');button.className='person-workitem-link';button.type='button';button.setAttribute('aria-label','查看工作单：'+title.textContent);title.before(button);button.append(title);button.onclick=e=>{e.stopPropagation();row.click()}})});const list=main.querySelector('.person-rail-list');if(list&&!list.dataset.grouped){list.dataset.grouped='true';let group=null;[...list.children].forEach(child=>{if(child.classList.contains('person-group-title')){group=document.createElement('div');group.className='person-function-group';list.insertBefore(group,child)}if(group)group.append(child)})}}const previousRender=render;render=function(){previousRender();stylePersonnel()};stylePersonnel()})();
